#include <bits/stdc++.h>
#define int long long
using namespace std;

int getLeastPrimeFactor(int n) {
    if (n % 2 == 0) return 2;

    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return i;
    }

    return n;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n;
        cin >> n;

        int a = getLeastPrimeFactor(n);
        cout << n / a << ' ' << n - n / a << '\n';
    }

    return 0;
}

